import {createHash} from 'node:crypto';
import {createDatabase,sql} from './dist/database.js';
import {loadConfig} from './dist/config.js';
const db=createDatabase(loadConfig(process.env));
const hash=rows=>createHash('sha256').update(JSON.stringify(rows)).digest('hex');
try {
 const state=await db.transaction().execute(async tx=>{
  await sql`SET TRANSACTION READ ONLY`.execute(tx);
  const identity=(await sql`SELECT current_database() AS db,host(inet_server_addr()) AS host,current_setting('server_version_num')::int/10000 AS major,ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()`.execute(tx)).rows[0];
  if(identity.db!=='tcdx-grc'||identity.host!=='192.168.2.40'||identity.major!==16||!identity.ssl)throw Error('QA_IDENTITY_REQUIRED');
  const subscriptions=(await sql`SELECT to_jsonb(s) AS row FROM platform.subscriptions s ORDER BY subscription_id`.execute(tx)).rows;
  const v1=(await sql`SELECT to_jsonb(pv) AS row FROM platform.plan_versions pv WHERE version_number=1 ORDER BY plan_version_id`.execute(tx)).rows;
  const entitlements=(await sql`SELECT to_jsonb(e) AS row FROM platform.entitlements e JOIN platform.plan_versions pv USING(plan_version_id) WHERE pv.version_number=1 ORDER BY entitlement_id`.execute(tx)).rows;
  const refs=(await sql`SELECT to_jsonb(rp) AS row FROM iam.role_permissions rp JOIN iam.permissions p USING(permission_id) WHERE p.permission_code IN ('compliance.framework.read','platform.membership_reference.read','privacy.retention_policy_reference.read') ORDER BY role_permission_id`.execute(tx)).rows;
  const roles=(await sql`SELECT to_jsonb(r) AS row FROM iam.roles r ORDER BY role_id`.execute(tx)).rows;
  const counts=(await sql`SELECT
   (SELECT count(*)::int FROM platform.schema_migrations) AS migrations,
   (SELECT count(*)::int FROM iam.service_principals WHERE lifecycle_state='active' AND ownership_class='PLATFORM_CONTROL' AND tenant_id IS NULL) AS active_platform_service_principals,
   (SELECT count(*)::int FROM ops_audit.audit_events WHERE command_code='phase6a3RolePermissionPublication') AS reference_publication_audits,
   (SELECT count(*)::int FROM ops_audit.audit_events WHERE command_code='phase6a3RbacResolutionR3') AS r3_audits,
   (SELECT count(*)::int FROM iam.permissions WHERE permission_code IN ('platform.subscription.read','platform.subscription.update','platform.commercial_catalog.publish') AND lifecycle_state='published') AS commercial_permissions,
   (SELECT count(*)::int FROM ops_audit.lifecycle_transition_definitions WHERE command_code IN ('subscription.change_plan','subscription_regulatory_pack.transfer_close','commercial_catalog.publish') AND lifecycle_state='published') AS commercial_lifecycle_registry_rows,
   (SELECT count(*)::int FROM platform.plan_versions WHERE version_number=2 AND lifecycle_state='published') AS v2,
   (SELECT count(*)::int FROM platform.entitlements e JOIN platform.plan_versions pv USING(plan_version_id) WHERE version_number=2) AS entitlements_v2,
   (SELECT count(*)::int FROM pg_constraint WHERE contype='f' AND NOT convalidated) AS unvalidated_fks,
   has_table_privilege(current_user,'iam.service_principals','INSERT') AS app_can_provision,
   has_table_privilege(current_user,'iam.permissions','INSERT') AS app_can_publish,
   (SELECT count(*)::int FROM regulatory.regulatory_packs WHERE lifecycle_state='draft') AS draft_packs,
   (SELECT count(*)::int FROM ops_audit.audit_events WHERE command_code='commercial_catalog.publish') AS catalog_audits,
   (SELECT count(*)::int FROM ops_audit.outbox_events WHERE event_type IN ('platform.commercial_catalog.published.v1','platform.plan_version.published.v1')) AS catalog_outbox`.execute(tx)).rows[0];
  const plans=(await sql`SELECT p.plan_code,pv.version_number::text,pv.lifecycle_state,
   to_char(pv.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS effective_from,
   pv.published_at IS NOT NULL AS published FROM platform.plan_versions pv JOIN platform.plans p USING(plan_id) ORDER BY plan_code,version_number`.execute(tx)).rows;
  const quotas=(await sql`SELECT p.plan_code,COALESCE(f.family_code,'TOTAL') AS dimension,u.limit_value::text AS value,u.unit,
   u.effective_to IS NULL AS open_ended FROM platform.usage_limits u JOIN platform.plan_versions pv USING(plan_version_id)
   JOIN platform.plans p USING(plan_id) LEFT JOIN platform.commercial_families f USING(commercial_family_id)
   WHERE pv.version_number=2 ORDER BY p.plan_code,dimension`.execute(tx)).rows;
  const publication=(await sql`SELECT
   (SELECT count(*)::int FROM ops_audit.audit_events WHERE command_code='commercial_catalog.publish'
     AND actor_user_identity_id IS NOT NULL AND actor_service_principal_id IS NULL AND outcome='success'
     AND ownership_class='PLATFORM_CONTROL' AND tenant_id IS NULL
     AND event_code IN ('audit.platform.commercial_catalog.publish.v1','audit.platform.plan_version.publish.v1')
     AND after_payload->>'manifest_sha256'='3e12e21ebc0ad31ea2e7f7ab96cc15a022252b2389fbe4d33ecf72208fc9a479') AS verified_material_audits,
   (SELECT count(DISTINCT aggregate_id)::int FROM ops_audit.outbox_events
     WHERE event_type IN ('platform.commercial_catalog.published.v1','platform.plan_version.published.v1')
      AND actor_user_identity_id IS NOT NULL AND actor_service_principal_id IS NULL AND ownership_class='PLATFORM_CONTROL'
      AND tenant_id IS NULL AND payload->>'manifest_sha256'='3e12e21ebc0ad31ea2e7f7ab96cc15a022252b2389fbe4d33ecf72208fc9a479') AS verified_outbox_aggregates,
   (SELECT count(*)::int FROM ops_audit.idempotency_records WHERE operation_code='commercialCatalogPublication'
      AND result_status_code='completed' AND request_hash='3e12e21ebc0ad31ea2e7f7ab96cc15a022252b2389fbe4d33ecf72208fc9a479') AS completed_publications,
   (SELECT count(*)::int FROM iam.role_permissions rp JOIN iam.permissions p USING(permission_id) JOIN iam.roles r USING(role_id)
    WHERE p.permission_code IN ('platform.subscription.read','platform.subscription.update','platform.commercial_catalog.publish')
    AND r.role_code='PLATFORM_ADMIN' AND r.is_baseline AND r.ownership_class='PLATFORM_CONTROL' AND r.tenant_id IS NULL
    AND rp.ownership_class='PLATFORM_CONTROL' AND rp.tenant_id IS NULL) AS commercial_admin_grants,
   (SELECT count(*)::int FROM iam.role_permissions rp JOIN iam.permissions p USING(permission_id) JOIN iam.roles r USING(role_id)
    WHERE p.permission_code IN ('platform.subscription.read','platform.subscription.update','platform.commercial_catalog.publish')
    AND NOT(r.role_code='PLATFORM_ADMIN' AND r.is_baseline AND r.ownership_class='PLATFORM_CONTROL' AND r.tenant_id IS NULL
    AND rp.ownership_class='PLATFORM_CONTROL' AND rp.tenant_id IS NULL)) AS unauthorized_commercial_grants,
   (SELECT count(*)::int FROM iam.service_principals sp JOIN ops_audit.audit_events a ON a.aggregate_id=sp.service_principal_id
    WHERE sp.principal_code='grc-qa-iam-publisher' AND sp.lifecycle_state='active' AND sp.ownership_class='PLATFORM_CONTROL' AND sp.tenant_id IS NULL
     AND sp.credential_ref='/run/secrets/iam_publisher_client_secret' AND a.command_code='servicePrincipalProvisionQa'
     AND a.after_payload->>'decision_id'='DR-STEP6A3-IAM-M2M-QA-20261014-01' AND a.after_payload->>'subject_sha256' IS NOT NULL) AS verified_machine_bindings,
   (SELECT count(*)::int FROM (SELECT aggregate_id FROM ops_audit.audit_events WHERE command_code='phase6a3RolePermissionPublication'
      GROUP BY aggregate_id HAVING count(*)<>1) x) AS duplicate_reference_audits`.execute(tx)).rows[0];
  return {identity,counts,quotas,publication,subscriptions_count:subscriptions.length,entitlements_v1_count:entitlements.length,
   fingerprints:{subscriptions:hash(subscriptions),plan_v1:hash(v1),entitlements_v1:hash(entitlements),reference_grants:hash(refs),roles:hash(roles)},plans};
 });
 console.log(JSON.stringify({status:'PASS_READONLY',at:new Date().toISOString(),...state}));
}catch(e){console.log(JSON.stringify({status:'FAIL',code:e.code??'QA_STATE_READ_FAILED'}));process.exitCode=1;}finally{await db.destroy();}
